query getChannel($uniqueName: String!, $now: DateTime, $loggedInUsername: String) {
  channels(where: {uniqueName: {eq: $uniqueName}}) {
    uniqueName
    displayName
    description
    ...ChannelIconFields
    channelBannerURL
    isFavorited(username: $loggedInUsername)
    rules
    locked
    lockedAt
    lockReason
    LockedBy {
      displayName
    }
    wikiEnabled
    eventsEnabled
    feedbackEnabled
    imageUploadsEnabled
    markdownImagesEnabled
    emojiEnabled
    downloadsEnabled
    allowedFileTypes
    WikiHomePage {
      id
      title
      body
      editReason
      slug
      createdAt
      updatedAt
      VersionAuthor {
        username
      }
    }
    PinnedWikiPages(sort: [{updatedAt: DESC}]) {
      id
      title
      slug
      updatedAt
    }
    Tags {
      text
    }
    Admins {
      ...AuthorFields
    }
    Bots {
      username
      displayName
      botProfileId
      isDeprecated
      SuspensionsConnection(
        where: {node: {OR: [{suspendedIndefinitely: {eq: true}}, {suspendedUntil_GT: $now}]}}
      ) {
        aggregate {
          count {
            nodes
          }
        }
      }
    }
    Moderators {
      displayName
    }
    SuspendedMods {
      modProfileName
    }
    SuspendedUsers {
      username
    }
    DiscussionChannelsConnection(
      where: {node: {AND: [{NOT: {Discussion: null}}, {NOT: {Discussion: {hasDownload: {eq: true}}}}]}}
    ) {
      aggregate {
        count {
          nodes
        }
      }
    }
    IssuesConnection(where: {node: {isOpen: {eq: true}}}) {
      aggregate {
        count {
          nodes
        }
      }
    }
    EventChannelsConnection(
      where: {node: {NOT: {archived: {eq: true}, Event: null}, Event: {canceled: {eq: false}, endTime_GT: $now}}}
    ) {
      aggregate {
        count {
          nodes
        }
      }
    }
    DefaultModRole {
      canHideComment
      canHideEvent
      canHideDiscussion
      canDeleteWiki
      canEditComments
      canEditDiscussions
      canEditEvents
      canGiveFeedback
      canOpenSupportTickets
      canCloseSupportTickets
      canReport
      canSuspendUser
    }
    ElevatedModRole {
      canHideComment
      canHideEvent
      canHideDiscussion
      canDeleteWiki
      canEditComments
      canEditDiscussions
      canEditEvents
      canGiveFeedback
      canOpenSupportTickets
      canCloseSupportTickets
      canReport
      canSuspendUser
    }
    SuspendedModRole {
      canHideComment
      canHideEvent
      canHideDiscussion
      canDeleteWiki
      canEditComments
      canEditDiscussions
      canEditEvents
      canGiveFeedback
      canOpenSupportTickets
      canCloseSupportTickets
      canReport
      canSuspendUser
    }
    DefaultChannelRole {
      canCreateComment
      canCreateDiscussion
      canCreateEvent
      canUpdateChannel
      canUploadFile
      canUpvoteComment
      canUpvoteDiscussion
      channelUniqueName
    }
    ElevatedChannelRole {
      canCreateComment
      canCreateDiscussion
      canCreateEvent
      canUpdateChannel
      canUploadFile
      canUpvoteComment
      canUpvoteDiscussion
      channelUniqueName
    }
    SuspendedRole {
      canCreateComment
      canCreateDiscussion
      canCreateEvent
      canUpdateChannel
      canUploadFile
      canUpvoteComment
      canUpvoteDiscussion
      channelUniqueName
    }
    FilterGroups(sort: [{order: ASC}]) {
      id
      key
      displayName
      mode
      uploadSelection
      order
      options(sort: [{order: ASC}]) {
        id
        value
        displayName
        order
      }
    }
  }
}

fragment AuthorFields on User {
  username
  displayName
  profilePicURL
  createdAt
  discussionKarma
  commentKarma
}

fragment ChannelIconFields on Channel {
  channelIconURL
}

query GetChannelPluginSettings($channelUniqueName: String!, $now: DateTime) {
  channels(where: {uniqueName: {eq: $channelUniqueName}}) {
    uniqueName
    displayName
    Bots {
      username
      displayName
      botProfileId
      isDeprecated
      SuspensionsConnection(
        where: {node: {OR: [{suspendedIndefinitely: {eq: true}}, {suspendedUntil_GT: $now}]}}
      ) {
        aggregate {
          count {
            nodes
          }
        }
      }
    }
    EnabledPluginsConnection {
      edges {
        node {
          id
          version
          Plugin {
            id
            name
            displayName
            description
            tags
          }
        }
        properties {
          settingsJson
        }
      }
    }
  }
}
